#!/usr/bin/env python3
"""Generate the exact protocol vocabulary; --check is a read-only drift check."""

import argparse
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
contract = json.loads((root / "Contracts/control-negotiation.json").read_text())

def literal(value):
    return json.dumps(value, ensure_ascii=True)

lines = [
    "// Generated by Scripts/generate-control-contract.py. Do not edit.",
    "// Source: Contracts/control-negotiation.json",
    "",
    "package enum ArkDeckControlProtocol {",
]
for field in ["legacyVersion", "targetVersion", "supportedExactVersions",
              "bootstrapVersion", "bootstrapMethod", "maximumBootstrapFrameBytes"]:
    lines.append(f"  package static let {field} = {literal(contract[field])}")
for field in ["targetMethods", "preBootstrapLegacyMethods"]:
    lines.append(f"  package static let {field}: Set<String> = {literal(contract[field])}")
lines.extend(["}", ""])
expected = "\n".join(lines)
destination = root / "Sources/ArkDeckCore/ControlProtocolGenerated.swift"
if args.check:
    if not destination.exists() or destination.read_text() != expected:
        raise SystemExit("control protocol generated source drifted; run generate-control-contract.py")
else:
    destination.write_text(expected)
